// Express com cors — explícito, com cache de preflight
const cors = require('cors');
const permitidos = new Set(['https://app.exemplo.com.br', 'https://admin.exemplo.com.br']);
app.use(cors({
  origin: (origin, cb) => cb(null, !origin || permitidos.has(origin)),  // não reflita qualquer origin
  credentials: true,
  allowedHeaders: ['Content-Type', 'Authorization', 'X-Request-Id'],
  maxAge: 600,   // preflight cacheado 10 min: metade dos round-trips somem
}));
// Registre ANTES das rotas e antes do middleware de auth — o preflight não carrega Authorization; se a auth roda antes, OPTIONS dá 401 e o browser mostra 'CORS error'.

