// API: ETag forte baseado em versão do banco, sem montar o corpo
app.get('/produtos/:id', async (req, res) => {
  const { rows: [v] } = await pool.query('SELECT updated_at FROM produtos WHERE id=$1', [req.params.id]);
  if (!v) return res.sendStatus(404);
  const etag = `"${v.updated_at.getTime()}"`;
  res.set({ ETag: etag, 'Cache-Control': 'private, no-cache' });   // sempre revalida, mas 304 sai barato
  if (req.get('If-None-Match') === etag) return res.sendStatus(304);
  const produto = await carregarProdutoCompleto(req.params.id);      // só quando mudou
  res.json(produto);
});

